  capability: CapabilityKey | CustomCapability;
  role: "sensor" | "actuator";
  /**
   * Display unit, e.g. '°C', 'W', 'kWh', '%'.
   */
  unit?: string;
  range?: {
    min: number;
    max: number;
    step?: number;
  };
  /**
   * Allowed string values, e.g. cover: open, closed, stopped.
   *
   * @minItems 1
   */
