/**
 * Body of every webhook delivery to a manufacturer endpoint (POST, application/json). Events describe the manufacturer's own fleet and never carry user or household data.
 */
export type WebhookEvent = {
  /**
   * Event id; the same event can be delivered more than once, de-duplicate by it.
   */
  id: string;
  type: EventType;
  /**
   * RFC 3339 date-time in UTC.
   */
  at: string;
  /**
   * Lowercase UUID (Lumio row ids are UUIDv7).
   */
  manufacturer_id: string;
  data: {
    [k: string]: unknown;
  };
} & (
  | {
      type: "device.provisioned";
      data: DeviceProvisioned;
      [k: string]: unknown;
    }
  | {
      type: "device.revoked";
      data: DeviceRef;
      [k: string]: unknown;
    }
  | {
      type: "device.claimed";
      data: DeviceClaimed;
      [k: string]: unknown;
    }
  | {
      type: "device.unclaimed";
      data: DeviceRef;
      [k: string]: unknown;
    }
  | {
      type: "hw_type.reviewed";
      data: HwTypeReviewed;
      [k: string]: unknown;
    }
  | {
      type: "firmware.verified";
      data: FirmwareRef;
      [k: string]: unknown;
    }
  | {
      type: "firmware.rejected";
      data: FirmwareRejected;
      [k: string]: unknown;
    }
  | {
      type: "campaign.status_changed";
      data: CampaignStatusChanged;
      [k: string]: unknown;
    }
  | {
      type: "ota.job_failed";
      data: OtaJobFailed;
      [k: string]: unknown;
    }
  | {
      type: "api_key.status_changed";
      data: ApiKeyStatusChanged;
      [k: string]: unknown;
    }
  | {
      type: "webhook.test";
      data: {
        [k: string]: unknown;
      };
      [k: string]: unknown;
    }
);

